engine.spec:
{
  "engine_identity": {
    "engine_id": "universal-platformer-core",
    "version": "8.5.0",
    "target_genre": "2D-plaftormer",
    "target_runtime": "Phaser 3 stable (CDN)",
    "deliverable_files": ["engine/index.html", "data/engine_spec.json"],
    "factory_contract": "window.GAME_DATA (theme, lore, entities, progression, assets) + ENGINE_SPEC"
  },
  "runtime": {
    "renderer": "Phaser.AUTO",
    "physics": "Arcade",
    "fixed_dt": 0.0166666,
    "render_dt": "variable",
    "scale_mode": "Phaser.Scale.FIT",
    "loop_phases": ["INPUT", "UPDATE", "PHYSICS", "RENDER", "EVENT"],
    "dependencies": ["phaser@3.80.1/dist/phaser.min.js"]
  },
  "factory_integration": {
    "input": "genre only",
    "output_stage_0_1": ["engine/index.html", "data/engine_spec.json"],
    "final_package": "game_build_package.zip",
    "data_source": "window.GAME_DATA OR data/*.json fetch"
  },
  "genre_analysis": {
    "genre_family": "action",
    "primary_genre": "2D-platformer",
    "secondary_genres": ["precision-platformer", "run-and-gun-lite", "collect-a-thon"],
    "subgenre": "micro-phase-precision-platformer",
    "hybrid_structure": "phase-sequenced platformer with checkpointed micro-levels",
    "player_role": "runner-jumper operator",
    "player_fantasy": "traverse hostile geometric terrain, outrun hazards, chain acrobatic movement",
    "primary_activity": "run, jump, dodge, collect, reach goal",
    "primary_decisions": ["jump timing", "route choice", "risk-vs-reward pickup", "upgrade pick"],
    "skill_model": "timing, spacing, route planning, hazard prediction, momentum control",
    "risk_model": "fall/contact death, checkpoint loss, missed optional collectibles",
    "reward_model": "score, currency, unlocks, upgrade picks, achievement progress",
    "progression_model": "vertical (difficulty) + horizontal (upgrades) + meta (unlocks)",
    "replayability_model": "micro-phases, choice pool, mutators, achievements, score chase"
  },
  "reference_inspiration": {
    "references": [
      "Modern Celeste-like precision movement pacing",
      "Super Meat Boy-style micro-rooms",
      "Hollow Knight-style layered parallax backgrounds",
      "Geometry Dash-style phase density and rhythm",
      "Ori-style juice feedback on every action"
    ],
    "retention_reasons": [
      "immediate responsiveness",
      "clear micro-goals",
      "checkpointing that respects player time",
      "upgrade choice tension",
      "satisfying juice feedback"
    ],
    "session_target": "10-15 minutes per macro-level"
  },
  "player_fantasy": {
    "who": "operator of a lightweight geometric runner",
    "what": "chain jumps, dashes and safe landings across micro-phases",
    "controls": "keyboard (A/D + Space + Shift) OR pointer/touch virtual buttons",
    "decisions": ["jump vs dash", "safe vs risky pickup", "which upgrade"],
    "optimizes": "completion time, collection %, achievement progress",
    "risks": "trap timing, gap width, enemy contact",
    "rewards": "coins, score, upgrade pick, achievement",
    "long_term_goal": "clear all macro-levels, unlock all upgrades, full achievements"
  },
  "gameplay_loops": {
    "primary_loop": {
      "steps": ["INPUT", "ACTION", "SYSTEM_RESPONSE", "CONSEQUENCE", "FEEDBACK", "REWARD_COST", "NEW_DECISION"],
      "example": "player presses jump -> character jumps -> gravity pulls -> lands or dies -> squash-stretch juice + sfx -> checkpoint or coin -> next hazard"
    },
    "secondary_loops": [
      "collect coin -> spend in meta -> unlock upgrade",
      "avoid enemy -> kill enemy via stomp -> score",
      "activate checkpoint -> respawn there on death"
    ],
    "meta_loop": "SESSION -> coins + achievements -> unlock upgrades -> new micro-phase options -> NEW SESSION",
    "endgame_loop": "all upgrades unlocked -> chase 100% collect + time-trial + mutators"
  },
  "core_architecture": {
    "entity_component_model": {
      "base_components": ["Transform", "Velocity", "Sprite", "Collider", "Health", "PlayerTag", "EnemyTag", "CoinTag", "TrapTag", "CheckpointTag", "GoalTag", "AIState", "FSM", "Animated"],
      "gameplay_components": ["Gravity", "Jump", "Dash", "DamageOnTouch", "Collectible", "Stompable"],
      "composition_rules": "entity = { id, components: Map }; behavior emerges from component sets; no inheritance; no 'type' field"
    },
    "system_order": [
      "InputSystem",
      "ModifierSystem",
      "RuleSystem",
      "AISystem",
      "MovementSystem",
      "GravitySystem",
      "CollisionSystem",
      "DeathSystem",
      "CheckpointSystem",
      "RenderSystem",
      "JuiceSystem"
    ],
    "event_bus": {
      "core_events": [
        "SESSION_STARTED", "SESSION_ENDED", "GAMEPLAY_START", "GAMEPLAY_STOP",
        "CORE_ACTION_PERFORMED", "PROGRESS_CHANGED", "REWARD_GRANTED",
        "ACHIEVEMENT_UNLOCKED", "ENTITY_CREATED", "ENTITY_DESTROYED",
        "STAGE_COMPLETED", "OBJECTIVE_COMPLETED", "ERROR_REPORTED",
        "AD_REQUESTED", "AD_RESULT",
        "PLATFORM_INITIALIZED", "PLATFORM_ERROR",
        "PLAYER_DIED", "CHECKPOINT_REACHED", "COIN_COLLECTED",
        "ENEMY_KILLED", "MICRO_PHASE_COMPLETED", "MICRO_PHASE_STARTED"
      ],
      "extension_events": ["CAMERA_SHAKE", "HITSTOP", "PARTICLE_BURST"]
    },
    "micro_animation_system": {
      "supported_classes": ["anim-idle", "anim-hover", "anim-interact", "anim-destroy", "none"],
      "implementation_rule": "Phaser 3 Tweens; driven by entities.json animation_class + interaction_class; no sprite sheets required",
      "trigger_mechanism": "state change OR pointerover/pointerdown OR event"
    }
  },
  "rule_engine": {
    "condition_types": ["HasComponent", "HasTag", "ValueCompare", "DistanceCheck", "EventMatch"],
    "effect_types": ["ModifyComponent", "EmitEvent", "SpawnEntity", "DestroyEntity", "ApplyModifier"],
    "sample_rules": [
      {
        "id": "coin_pickup",
        "condition": [{"type": "EventMatch", "event": "COIN_COLLECTED"}],
        "effect": [{"type": "EmitEvent", "event": "REWARD_GRANTED", "payload": {"coin": 1}}],
        "priority": 10
      },
      {
        "id": "enemy_stomp",
        "condition": [{"type": "EventMatch", "event": "ENEMY_KILLED"}],
        "effect": [{"type": "EmitEvent", "event": "REWARD_GRANTED", "payload": {"score": 50}}],
        "priority": 10
      }
    ]
  },
  "modifier_system": {
    "formula": "(BASE + FLAT) * MULT_PRODUCT * CONDITIONAL",
    "stacking_rules": "stackable_add for FLAT, multiply for MULT",
    "priority_model": "source_priority ASC then insertion_order ASC",
    "duration_model": "permanent | timed | until_event",
    "modifier_types": ["FLAT", "MULT", "CONDITIONAL"],
    "targets": ["player.speed", "player.jump_force", "player.dash_cooldown", "player.max_hp", "coin.multiplier"]
  },
  "ai_architecture": {
    "model": "FSM",
    "state_definitions": ["idle", "patrol", "alert", "chase", "attack", "return", "dead"],
    "transition_conditions": [
      "patrol -> chase: distance(player) < alert_radius",
      "chase -> attack: distance(player) < attack_range",
      "attack -> chase: cooldown_elapsed",
      "any -> dead: health <= 0"
    ]
  },
  "render_layers": [
    {"id": "background_far",  "layer": "LAYER_BACKGROUND", "z": -300, "has_collision": false, "parallax": true},
    {"id": "background_mid",  "layer": "LAYER_BACKGROUND", "z": -200, "has_collision": false, "parallax": true},
    {"id": "background_near", "layer": "LAYER_BACKGROUND", "z": -100, "has_collision": false, "parallax": true},
    {"id": "gameplay",        "layer": "LAYER_GAMEPLAY",   "z": 0,    "has_collision": true,  "parallax": false},
    {"id": "foreground",      "layer": "LAYER_FOREGROUND", "z": 100,  "has_collision": false, "parallax": false},
    {"id": "ui",              "layer": "LAYER_UI",         "z": 1000, "has_collision": false, "parallax": false}
  ],
  "progression_data_format": {
    "description": "Формат уровня в progression.json",
    "macro_level_structure": {
      "required_fields": ["level_id", "name", "micro_phases", "density_metrics", "difficulty_curve"],
      "density_metrics": {
        "min_encounters": 12,
        "min_collectibles": 8,
        "min_hazards": 6,
        "min_micro_phases": 6,
        "target_minutes": [10, 15]
      }
    },
    "micro_level_structure": {
      "required_fields": [
        "micro_level_id", "sequence_index", "phase", "objective",
        "world_or_board", "spatial_extent", "entities_in_zone", "decorative_layout"
      ],
      "entities_in_zone_schema": {
        "entity_id": "string (ref entities.json)",
        "instance_count": "integer >= 1",
        "entity_category": "gameplay",
        "row": "integer",
        "col": "integer"
      },
      "decorative_layout_schema": {
        "entity_id": "string (ref entities.json)",
        "instance_count": "integer >= 1",
        "render_layer": "background_far | background_mid | background_near | foreground",
        "z_index": "integer",
        "has_collision": "false",
        "parallax_factor": "number 0.0-1.0",
        "row": "integer | null",
        "col": "integer | null"
      },
      "layer_mapping_rules": {
        "background_far":  "LAYER_BACKGROUND (z<0, parallax HIGH, ~0.15)",
        "background_mid":  "LAYER_BACKGROUND (z<0, parallax MEDIUM, ~0.4)",
        "background_near": "LAYER_BACKGROUND (z<0, parallax LOW, ~0.7)",
        "foreground":      "LAYER_FOREGROUND (z>0, parallax none)"
      }
    }
  },
  "game_data_schema": {
    "theme.json": {
      "required": ["palette", "texts", "font", "audio", "save_key"],
      "palette": {"bg": "hex", "fg": "hex", "accent": "hex", "danger": "hex", "reward": "hex"}
    },
    "lore.json": {
      "required": ["world_summary", "tone", "factions_or_contexts", "key_concepts"]
    },
    "entities.json": {
      "required": ["player_or_core_agent", "opposing_or_active_forces", "player_tools_or_actions", "environment_or_context_entities"],
      "entity_schema": {
        "entity_id": "string",
        "components": {"type": "object"},
        "tags": ["string"],
        "animation_class": "anim-idle | anim-pulse | none",
        "interaction_class": "anim-squash | anim-flash | none",
        "visual": {"shape": "rect|circle|poly", "color_key": "accent|fg|danger|reward|bg", "size": [w, h]}
      }
    },
    "progression.json": {
      "required": ["stages_or_levels", "density_metrics", "choice_pool", "achievements", "tutorial", "meta_upgrades", "difficulty_overrides"]
    },
    "asset_spec.json": {
      "required": ["images", "audio", "animations", "fonts", "effects", "placeholders"]
    }
  },
  "systems": [
    {"system_id": "InputSystem",      "purpose": "abstract input -> commands",     "category": "core",      "inputs": ["raw input"], "outputs": ["Command"], "events_emitted": ["CORE_ACTION_PERFORMED"]},
    {"system_id": "MovementSystem",   "purpose": "apply velocity to transform",     "category": "physics"},
    {"system_id": "GravitySystem",    "purpose": "apply gravity to velocity",       "category": "physics"},
    {"system_id": "CollisionSystem",  "purpose": "resolve gameplay-layer collisions","category": "physics"},
    {"system_id": "AISystem",         "purpose": "drive FSM transitions",            "category": "ai"},
    {"system_id": "RuleSystem",       "purpose": "evaluate data rules",              "category": "core"},
    {"system_id": "ModifierSystem",   "purpose": "compute final values",             "category": "core"},
    {"system_id": "CheckpointSystem", "purpose": "track + respawn on mid-stage CP",  "category": "gameplay"},
    {"system_id": "DeathSystem",      "purpose": "kill player on hazard contact",    "category": "gameplay"},
    {"system_id": "RenderSystem",     "purpose": "render layers with parallax",      "category": "render"},
    {"system_id": "JuiceSystem",      "purpose": "particles/tweens/hitstop",         "category": "render"}
  ],
  "system_dependencies": {
    "InputSystem": [],
    "ModifierSystem": ["InputSystem"],
    "RuleSystem": ["ModifierSystem"],
    "AISystem": ["RuleSystem"],
    "MovementSystem": ["AISystem"],
    "GravitySystem": ["MovementSystem"],
    "CollisionSystem": ["GravitySystem"],
    "CheckpointSystem": ["CollisionSystem"],
    "DeathSystem": ["CollisionSystem"],
    "RenderSystem": ["DeathSystem"],
    "JuiceSystem": ["RenderSystem"]
  },
  "system_interactions": [
    {"source": "InputSystem", "target": "MovementSystem", "event": "CORE_ACTION_PERFORMED", "effect": "set velocity"},
    {"source": "CollisionSystem", "target": "DeathSystem", "event": "PLAYER_DIED", "effect": "respawn"},
    {"source": "CollisionSystem", "target": "RuleSystem", "event": "COIN_COLLECTED", "effect": "reward"}
  ],
  "state_model": {
    "ENGINE_STATE": ["initialized", "running", "paused", "shutdown"],
    "RUNTIME_STATE": ["systems", "entities", "eventBus"],
    "SESSION_STATE": ["current_level", "current_micro_phase", "score", "coins", "time"],
    "WORLD_STATE": ["spawned_entities", "decorations"],
    "PLAYER_STATE": ["position", "velocity", "hp", "checkpoint"],
    "PROGRESSION_STATE": ["unlocked_upgrades", "achievements", "meta_coins"],
    "META_STATE": ["version", "migrations"],
    "PERSISTENT_STATE": ["localStorage"],
    "DERIVED_STATE": ["computed_final_values"],
    "PRESENTATION_STATE": ["camera", "hud", "screen"]
  },
  "entity_model": {
    "structure": "{ id: string, components: Map<name, POD> }",
    "no_inheritance": true,
    "runtime_composition": true,
    "queries": "system declares required component set"
  },
  "component_model": {
    "POD_only": true,
    "no_methods": true,
    "examples": {
      "Transform": {"x": 0, "y": 0},
      "Velocity":  {"vx": 0, "vy": 0},
      "Sprite":    {"key": "shape", "w": 32, "h": 32, "color": 0xffffff, "layer": "gameplay", "z": 0},
      "Collider":  {"w": 32, "h": 32, "static": false},
      "Health":    {"hp": 1, "max": 1},
      "PlayerTag": {},
      "EnemyTag":  {"behavior": "patrol", "alert_radius": 200, "speed": 80},
      "CoinTag":   {"value": 1},
      "TrapTag":   {"kind": "spike"},
      "CheckpointTag": {"index": 0},
      "GoalTag":   {},
      "FSM":       {"current": "patrol", "transitions": []},
      "Animated":  {"animation_class": "anim-idle", "interaction_class": "anim-squash"}
    }
  },
  "content_domains": ["entities", "progression", "theme", "lore", "assets", "rules"],
  "rules": {
    "description": "data-driven rules read from GAME_DATA.rules or embedded",
    "runtime_evaluation": "per frame, priority ordered"
  },
  "conditions": ["HasComponent", "HasTag", "ValueCompare", "DistanceCheck", "EventMatch"],
  "effects": ["ModifyComponent", "EmitEvent", "SpawnEntity", "DestroyEntity", "ApplyModifier"],
  "modifiers": {
    "types": ["FLAT", "MULT", "CONDITIONAL"],
    "stacking": "FLAT adds, MULT multiplies, CONDITIONAL gate"
  },
  "events": {
    "core": [
      "SESSION_STARTED", "SESSION_ENDED", "GAMEPLAY_START", "GAMEPLAY_STOP",
      "CORE_ACTION_PERFORMED", "PROGRESS_CHANGED", "REWARD_GRANTED",
      "ACHIEVEMENT_UNLOCKED", "ENTITY_CREATED", "ENTITY_DESTROYED",
      "STAGE_COMPLETED", "OBJECTIVE_COMPLETED", "ERROR_REPORTED",
      "AD_REQUESTED", "AD_RESULT", "PLAYER_DIED", "CHECKPOINT_REACHED",
      "COIN_COLLECTED", "ENEMY_KILLED", "MICRO_PHASE_STARTED", "MICRO_PHASE_COMPLETED"
    ]
  },
  "progression": {
    "curves": ["linear", "exponential", "logistic", "stepped", "polynomial", "soft-cap", "hard-cap", "diminishing-return"],
    "macro_levels": "each with micro_phases[]",
    "mid_stage_checkpointing": true,
    "upgrade_choice_after": "every 2 micro_phases or on level completion"
  },
  "economy": {
    "sources": ["coin pickup", "enemy kill reward", "level completion bonus"],
    "sinks": ["meta_upgrade purchase"],
    "currency": ["coins"],
    "scaling": "linear with soft-cap"
  },
  "rewards": {
    "types": ["currency", "unlock", "score", "ability", "content", "achievement"]
  },
  "objectives": {
    "types": ["reach_goal", "collect_n", "survive_time", "kill_n"]
  },
  "achievements": {
    "count_min": 5,
    "checked_via": "EventBus subscriptions"
  },
  "AI": {
    "model": "FSM",
    "states": ["idle", "patrol", "alert", "chase", "attack", "return", "dead"]
  },
  "simulation": {"applies": false, "genre_equivalent": "hazard/enemy state machine"},
  "procedural_generation": {
    "supported": true,
    "seed": "level_id hash",
    "usage": "optional decoration scatter if data requests"
  },
  "difficulty": {
    "dimensions": ["hazard density", "gap width", "enemy speed", "time pressure", "checkpoint spacing"]
  },
  "replayability": {
    "mechanisms": ["upgrade choice pool", "achievements", "collect %", "time-trial", "mutators"]
  },
  "endgame": {
    "mechanisms": ["100% collection", "time-trial", "mutator runs", "all upgrades"]
  },
  "UI": {
    "screens": ["LoadingScene", "PreloadScene", "MenuScene", "GameScene", "HUDScene", "PauseScene", "ResultScene", "UpgradeScene", "SettingsScene", "AchievementsScene"],
    "model": "GameState -> Presentation -> UI"
  },
  "screens": {
    "required_categories": [
      "loading", "asset_preload", "main_menu", "gameplay_hud",
      "pause", "session_result", "genre_specific (upgrade_choice)"
    ]
  },
  "onboarding": {
    "read_from": "GAME_DATA.progression.tutorial",
    "steps_min": 3,
    "no_hardcoded_text": true
  },
  "settings": {
    "fields": ["music_volume", "sfx_volume", "music_on", "sfx_on", "effects_quality", "language"],
    "persisted": true
  },
  "input": {
    "keyboard": {"left": "A/LEFT", "right": "D/RIGHT", "jump": "SPACE/UP", "dash": "SHIFT", "pause": "ESC"},
    "touch": "virtual buttons",
    "abstract_commands": ["MOVE_LEFT", "MOVE_RIGHT", "JUMP", "DASH", "PAUSE"]
  },
  "rendering": {
    "layers": ["LAYER_BACKGROUND", "LAYER_GAMEPLAY", "LAYER_FOREGROUND", "LAYER_UI"],
    "collisions_only_in": ["LAYER_GAMEPLAY"],
    "parallax_supported": true,
    "decorative_layout_supported": true
  },
  "audio": {
    "channels": ["master", "music", "sfx"],
    "adaptive_music_states": ["calm", "intense"],
    "pitch_jitter": "±5-10%",
    "sfx_variants_per_event": 2
  },
  "assets": {
    "types": ["images", "audio", "animations", "fonts", "effects", "placeholders"],
    "fallback": "procedural placeholders generated in-engine"
  },
  "localization": {
    "keys": "all user-facing strings via theme.texts.*",
    "fallback_lang": "en"
  },
  "save": {
    "storage": "localStorage",
    "version_field": "save.version",
    "migration": true,
    "mid_stage_checkpointing": true,
    "corruption_handling": "reset with diagnostic"
  },
  "offline_progress": {"applies": false},
  "performance": {
    "object_pooling": ["particles", "sfx players"],
    "no_hot_allocations": true,
    "rendering": "canvas"
  },
  "platform_adapter": {
    "methods": ["gameplayStart", "gameplayStop", "rewardAd", "interstitialAd", "submitScore", "isAdAvailable"],
    "events": ["AD_REQUESTED", "AD_RESULT", "PLATFORM_INITIALIZED", "PLATFORM_ERROR"],
    "fallback": "no-op adapter"
  },
  "validation": {
    "schema_validation": true,
    "reference_validation": true,
    "safe_defaults": true,
    "debug_mode": "?debug=1"
  },
  "testing": {
    "harness": "internal boot with synthetic GAME_DATA",
    "modes": ["minimal", "empty", "corrupted"]
  },
  "accessibility": {
    "minimal": ["readable HUD scale", "no reliance on color only", "pause anytime"]
  },
  "visual_coherence_protocol": {
    "strict_palette_locking": true,
    "grid_snapping": 32,
    "strict_layer_separation": true,
    "zero_logic_decorations": true
  }
}
